// Compute the SAH cost for a split.
// ns1, ns2: number of primitives on the left/right side.
// leftArea, rightArea: surface area of the left/right bounding boxes.
// invS: inverse of the total surface area of the node being split.
// Taabb: traversal cost for an internal node (AABB).
// Ttri: intersection cost for a primitive (triangle).
// The SAH cost is:
//   cost = Taabb + (leftArea * invS) * ns1 * Ttri + (rightArea * invS) * ns2 * Ttri
// This formulation follows the standard Surface Area Heuristic used in BVH construction.
T leftCost = static_cast<T>(ns1) * leftArea * invS * Ttri;
T rightCost = static_cast<T>(ns2) * rightArea * invS * Ttri;
return Taabb + leftCost + rightCost;

